/**
 * QuizLens AI - Direct Client-Side AI Solver (Serverless / No Backend Needed)
 * Allows the extension to solve questions directly with Gemini, Groq, or OpenRouter
 */

import { AnswerResult, OptionKey, QuestionOptions } from '../shared/types';

const SYSTEM_PROMPT = `You are QuizLens AI, an expert examination and quiz solver.
Your task is to analyze questions of diverse formats and accurately determine the correct answer.

QUESTION FORMAT GUIDELINES:
1. Multiple-choice (Single option):
   - Choose the single most accurate letter: "A", "B", "C", "D", "E"...
2. Binary / True-False (2 options: Đúng/Sai, True/False, Có/Không, Yes/No):
   - Choose "A" or "B" (or "Đúng" / "Sai").
3. Multi-select (Tick / Checkbox / "Chọn các đáp án đúng", "Chọn 2 đáp án..."):
   - Return ALL correct option letters separated by commas, e.g. "A, C" or "A, B, D".
   - In "answerText", list the content of the selected options.
4. Fill-in-the-blank (Điền vào ô trống: ..., ___, [...], (...)):
   - If options (A, B, C, D) are provided: Choose the best option letter.
   - If NO options are provided (open-ended fill-in-the-blank): Put the exact missing word/phrase in "answer" (e.g. "54", "Lục lạp", "Paris"), and the full completed sentence in "answerText".
5. Unlabeled / Numbered options:
   - If options were numbered 1, 2, 3, 4, they are mapped to A, B, C, D. Choose the corresponding letter.
6. Direct questions without options (Chỉ có câu hỏi, không có đáp án lựa chọn):
   - Determine the correct answer directly.
   - Put ONLY the most CONCISE, DIRECT answer in "answer" (e.g. "Hà Nội", "5 cm", "Nitrogen (N2)", "object", "1954", "William Shakespeare"). Keep it strictly to the core answer word, number, or key term.
   - In "answerText", provide a brief 1-sentence explanation.

RESPONSE SCHEMA:
Return ONLY raw JSON with no markdown wrapping:
{
  "status": "SUCCESS",
  "answer": "<Letter(s) e.g. 'A', 'B', 'A, C' OR concise direct answer for questions without options>",
  "answerText": "<exact text of option(s) or brief 1-sentence explanation>",
  "confidence": 0.95
}
If ambiguous or cannot determine, return:
{
  "status": "UNKNOWN",
  "answer": null,
  "answerText": null,
  "confidence": 0
}`;

function buildUserContent(question: string, options: QuestionOptions, questionType?: string): string {
  const optionsEntries = Object.entries(options).filter(
    ([_, val]) => typeof val === 'string' && val.trim().length > 0
  );

  let optionsText = '';
  if (optionsEntries.length > 0) {
    optionsText = optionsEntries.map(([key, val]) => `${key}. ${val}`).join('\n');
  }

  let text = `CÂU HỎI:\n${question}`;
  if (questionType) {
    text += `\n[Loại câu hỏi: ${questionType}]`;
  }
  if (optionsText) {
    text += `\n\nCÁC PHƯƠNG ÁN:\n${optionsText}`;
  } else {
    text += `\n\n(Câu hỏi trực tiếp không có phương án lựa chọn sẵn. YÊU CẦU: Hãy trả về đáp án THẬT NGẮN GỌN (chỉ từ khóa, tên, con số hoặc kết quả chính xác) vào trường "answer" và giải thích ngắn 1 câu vào "answerText".)`;
  }
  text += `\n\nTrả về duy nhất định dạng JSON:`;
  return text;
}

function buildPrompt(question: string, options: QuestionOptions, questionType?: string): string {
  return `${SYSTEM_PROMPT}\n\n${buildUserContent(question, options, questionType)}`;
}

function parseJsonResult(raw: string): AnswerResult {
  if (!raw) return { status: 'UNKNOWN', answer: null, answerText: null, confidence: 0 };

  let cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  cleaned = cleaned.replace(/,\s*([\}\]])/g, '$1');

  try {
    const parsed = JSON.parse(cleaned);
    let rawAnswer = parsed.answer != null ? String(parsed.answer).trim() : null;
    if (rawAnswer && /^[a-hA-H](?:[\s,;]+[a-hA-H])*$/.test(rawAnswer)) {
      rawAnswer = rawAnswer.toUpperCase().replace(/\s*[,;]\s*/g, ', ');
    }

    if (rawAnswer) {
      return {
        status: 'SUCCESS',
        answer: rawAnswer,
        answerText: parsed.answerText || null,
        confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.95
      };
    }
  } catch (e) {
    const match = raw.match(/"answer"\s*:\s*"([^"]+)"/i);
    if (match) {
      let letter = match[1].trim();
      if (/^[a-hA-H](?:[\s,;]+[a-hA-H])*$/.test(letter)) {
        letter = letter.toUpperCase().replace(/\s*[,;]\s*/g, ', ');
      }
      return {
        status: 'SUCCESS',
        answer: letter,
        answerText: null,
        confidence: 0.8
      };
    }
  }

  return { status: 'UNKNOWN', answer: null, answerText: null, confidence: 0 };
}

/**
 * Solve with Google Gemini directly with auto-fallback on 503 / 429 / 404
 */
export async function solveWithGeminiDirect(
  question: string,
  options: QuestionOptions,
  apiKey: string,
  modelName: string = 'gemini-2.0-flash',
  questionType?: string
): Promise<AnswerResult> {
  const prompt = buildPrompt(question, options, questionType);
  // Put high-capacity stable production models first to prevent 503 High Demand spikes
  const candidateModels = [
    modelName,
    'gemini-2.0-flash',
    'gemini-1.5-flash',
    'gemini-1.5-flash-latest',
    'gemini-2.5-flash'
  ];
  const uniqueModels = [...new Set(candidateModels)];

  let lastError = '';

  for (const model of uniqueModels) {
    try {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.1 }
        })
      });

      if (!response.ok) {
        // If 404 (not found), 503 (high demand) or 429 (rate limit), continue to next model!
        if (response.status === 404 || response.status === 503 || response.status === 429) {
          lastError = `Mô hình ${model} đang bận (${response.status}), đang thử mô hình tiếp theo...`;
          continue;
        }

        if (response.status === 400 || response.status === 403) {
          throw new Error('Gemini API Key không hợp lệ. Vui lòng kiểm tra lại key.');
        }

        const errText = await response.text();
        lastError = `Gemini Error (${response.status}): ${errText}`;
        continue;
      }

      const data = await response.json();
      const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
      const result = parseJsonResult(text);
      result.provider = `gemini (${model})`;
      return result;
    } catch (e: any) {
      if (e.message.includes('không hợp lệ')) throw e;
      lastError = e.message;
    }
  }

  // If all models failed with 503 or overload
  if (lastError.includes('503') || lastError.includes('high demand') || lastError.includes('bận')) {
    throw new Error(
      'Máy chủ Google Gemini đang bị quá tải tạm thời (503 High Demand). Vui lòng thử lại sau vài giây hoặc chuyển sang Groq Cloud (miễn phí, siêu tốc, không bị quá tải).'
    );
  }

  throw new Error(lastError || 'Không thể kết nối đến Gemini API. Hãy thử lại hoặc chuyển sang Groq.');
}

/**
 * Solve with Groq directly (Ultra-fast)
 */
/**
 * Fetches the list of active models directly from Groq for the given key
 */
async function getGroqLiveModels(apiKey: string): Promise<string[]> {
  try {
    const res = await fetch('https://api.groq.com/openai/v1/models', {
      headers: { 'Authorization': `Bearer ${apiKey.trim()}` }
    });
    if (res.status === 401) {
      throw new Error('Groq API Key không hợp lệ. Vui lòng lấy key mới tại console.groq.com/keys');
    }
    if (res.ok) {
      const data = await res.json();
      return (data.data || [])
        .map((m: any) => m.id as string)
        .filter((id: string) => !id.includes('whisper') && !id.includes('guard'));
    }
  } catch (e: any) {
    if (e.message.includes('không hợp lệ')) throw e;
  }
  return [];
}

export async function solveWithGroqDirect(
  question: string,
  options: QuestionOptions,
  apiKey: string,
  modelName: string = 'llama-3.3-70b-versatile',
  questionType?: string
): Promise<AnswerResult> {
  const cleanKey = (apiKey || '').trim();
  if (!cleanKey) {
    throw new Error('Chưa có Groq API Key. Vui lòng nhập key trong Popup!');
  }

  // 1. Fetch live models available specifically for this key
  const liveModels = await getGroqLiveModels(cleanKey);

  const candidateModels: string[] = [];
  if (modelName && (liveModels.length === 0 || liveModels.includes(modelName))) {
    candidateModels.push(modelName);
  }
  for (const m of liveModels) {
    if (!candidateModels.includes(m)) candidateModels.push(m);
  }
  if (candidateModels.length === 0) {
    candidateModels.push(
      modelName || 'llama-3.3-70b-versatile',
      'llama-3.3-70b-versatile',
      'llama-3.1-8b-instant'
    );
  }

  const userContent = buildUserContent(question, options, questionType);

  let lastError = '';

  for (const model of candidateModels) {
    try {
      const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cleanKey}`
        },
        body: JSON.stringify({
          model,
          messages: [
            { role: 'system', content: SYSTEM_PROMPT },
            { role: 'user', content: userContent }
          ],
          temperature: 0.1,
          max_tokens: 300
        })
      });

      if (!response.ok) {
        let errDetail = '';
        try {
          const errData = await response.json();
          errDetail = errData?.error?.message || '';
        } catch (_) {
          try { errDetail = await response.text(); } catch (_) {}
        }

        if (response.status === 401) {
          throw new Error('Groq API Key không hợp lệ. Vui lòng kiểm tra lại key tại console.groq.com');
        }
        if (response.status === 429) {
          throw new Error('Groq API đạt giới hạn Rate Limit. Thử lại sau ít phút.');
        }

        lastError = errDetail ? `Groq (${model}): ${errDetail}` : `Groq Error (${response.status})`;

        // If error message indicates model is decommissioned or not found, try next candidate model
        if (errDetail.toLowerCase().includes('model') || response.status === 404) {
          continue;
        }

        // Other errors (e.g. invalid request format): throw immediately
        throw new Error(lastError);
      }

      const data = await response.json();
      const text = data.choices?.[0]?.message?.content || '';
      const result = parseJsonResult(text);
      result.provider = `groq (${model})`;
      return result;
    } catch (e: any) {
      if (e.message.includes('không hợp lệ') || e.message.includes('Rate Limit') || e.message.includes('Groq:')) throw e;
      lastError = e.message;
    }
  }

  throw new Error(lastError || 'Không thể kết nối đến Groq API');
}

/**
 * Solve with OpenRouter directly
 */
export async function solveWithOpenRouterDirect(
  question: string,
  options: QuestionOptions,
  apiKey: string,
  modelName: string = 'meta-llama/llama-3.3-70b-instruct:free',
  questionType?: string
): Promise<AnswerResult> {
  const prompt = buildPrompt(question, options, questionType);
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
      'HTTP-Referer': 'https://quizlens.ai',
      'X-Title': 'QuizLens AI'
    },
    body: JSON.stringify({
      model: modelName,
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.1,
      max_tokens: 300
    })
  });

  if (!response.ok) {
    if (response.status === 401) throw new Error('OpenRouter API Key không hợp lệ.');
    throw new Error(`OpenRouter Error (${response.status})`);
  }

  const data = await response.json();
  const text = data.choices?.[0]?.message?.content || '';
  const result = parseJsonResult(text);
  result.provider = `openrouter (${modelName})`;
  return result;
}

/**
 * Solve with OpenAI (ChatGPT) directly
 */
export async function solveWithOpenAIDirect(
  question: string,
  options: QuestionOptions,
  apiKey: string,
  modelName: string = 'gpt-4o-mini',
  questionType?: string
): Promise<AnswerResult> {
  const cleanKey = (apiKey || '').trim();
  if (!cleanKey) {
    throw new Error('Chưa có OpenAI API Key. Vui lòng nhập key trong Popup!');
  }

  const userContent = buildUserContent(question, options, questionType);

  const candidateModels = [modelName || 'gpt-4o-mini', 'gpt-4o-mini', 'gpt-4o', 'gpt-3.5-turbo'];
  const uniqueModels = [...new Set(candidateModels)];

  let lastError = '';

  for (const model of uniqueModels) {
    try {
      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cleanKey}`
        },
        body: JSON.stringify({
          model,
          messages: [
            { role: 'system', content: SYSTEM_PROMPT },
            { role: 'user', content: userContent }
          ],
          response_format: { type: 'json_object' },
          temperature: 0.1,
          max_tokens: 300
        })
      });

      if (!response.ok) {
        let errDetail = '';
        try {
          const errData = await response.json();
          errDetail = errData?.error?.message || '';
        } catch (_) {
          try { errDetail = await response.text(); } catch (_) {}
        }

        if (response.status === 401) {
          throw new Error('OpenAI API Key không hợp lệ. Vui lòng kiểm tra lại key tại platform.openai.com/api-keys');
        }
        if (response.status === 429) {
          throw new Error('OpenAI API hết hạn ngạch hoặc đạt giới hạn Rate Limit.');
        }

        lastError = errDetail ? `OpenAI (${model}): ${errDetail}` : `OpenAI Error (${response.status})`;

        if (errDetail.toLowerCase().includes('model') || response.status === 404) {
          continue;
        }

        throw new Error(lastError);
      }

      const data = await response.json();
      const text = data.choices?.[0]?.message?.content || '';
      const result = parseJsonResult(text);
      result.provider = `openai (${model})`;
      return result;
    } catch (e: any) {
      if (e.message.includes('không hợp lệ') || e.message.includes('Rate Limit') || e.message.includes('OpenAI:')) throw e;
      lastError = e.message;
    }
  }

  throw new Error(lastError || 'Không thể kết nối đến OpenAI API');
}

/**
 * Solve with DeepSeek directly (R1 / V3)
 */
export async function solveWithDeepSeekDirect(
  question: string,
  options: QuestionOptions,
  apiKey: string,
  modelName: string = 'deepseek-chat',
  questionType?: string
): Promise<AnswerResult> {
  const cleanKey = (apiKey || '').trim();
  if (!cleanKey) {
    throw new Error('Chưa có DeepSeek API Key. Vui lòng nhập key trong Popup!');
  }

  const userContent = buildUserContent(question, options, questionType);

  const candidateModels = [modelName || 'deepseek-chat', 'deepseek-chat', 'deepseek-reasoner'];
  const uniqueModels = [...new Set(candidateModels)];

  let lastError = '';

  for (const model of uniqueModels) {
    try {
      const isReasoner = model === 'deepseek-reasoner';
      const bodyPayload: any = {
        model,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: userContent }
        ],
        max_tokens: isReasoner ? 1000 : 400
      };

      // deepseek-chat supports response_format and temperature; deepseek-reasoner restricts some
      if (!isReasoner) {
        bodyPayload.response_format = { type: 'json_object' };
        bodyPayload.temperature = 0.1;
      }

      const response = await fetch('https://api.deepseek.com/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${cleanKey}`
        },
        body: JSON.stringify(bodyPayload)
      });

      if (!response.ok) {
        let errDetail = '';
        try {
          const errData = await response.json();
          errDetail = errData?.error?.message || '';
        } catch (_) {
          try { errDetail = await response.text(); } catch (_) {}
        }

        if (response.status === 401) {
          throw new Error('DeepSeek API Key không hợp lệ. Vui lòng kiểm tra lại key tại platform.deepseek.com/api_keys');
        }
        if (response.status === 402) {
          throw new Error('Tài khoản DeepSeek chưa có số dư (Insufficient Balance). Vui lòng nạp credit tại platform.deepseek.com');
        }
        if (response.status === 429) {
          throw new Error('DeepSeek API đạt giới hạn Rate Limit. Thử lại sau ít phút.');
        }

        lastError = errDetail ? `DeepSeek (${model}): ${errDetail}` : `DeepSeek Error (${response.status})`;

        if (errDetail.toLowerCase().includes('model') || response.status === 404) {
          continue;
        }

        throw new Error(lastError);
      }

      const data = await response.json();
      const text = data.choices?.[0]?.message?.content || '';
      const result = parseJsonResult(text);
      result.provider = `deepseek (${model})`;
      return result;
    } catch (e: any) {
      if (e.message.includes('không hợp lệ') || e.message.includes('số dư') || e.message.includes('Rate Limit') || e.message.includes('DeepSeek:')) throw e;
      lastError = e.message;
    }
  }

  throw new Error(lastError || 'Không thể kết nối đến DeepSeek API');
}
