/**
 * QuizLens AI - Background Service Worker (Manifest V3)
 * Supports Direct AI Calling (No Backend Needed) as well as Backend Proxy Mode
 */

import { DEFAULT_SETTINGS } from '../shared/constants';
import { ExtensionSettings, AnswerResult, ApiResponse, AnalyzeRequestPayload } from '../shared/types';
import { RuntimeMessage } from '../shared/messages';
import { solveWithGeminiDirect, solveWithGroqDirect, solveWithOpenRouterDirect, solveWithOpenAIDirect, solveWithDeepSeekDirect } from './direct-ai';

// Initialize default settings and context menus on extension install
chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.sync.get('settings');
  if (!existing || !existing.settings) {
    await chrome.storage.sync.set({ settings: DEFAULT_SETTINGS });
  }

  // Create right-click context menu
  try {
    chrome.contextMenus.create({
      id: 'quizlens-solve-selection',
      title: 'Giải bằng QuizLens AI',
      contexts: ['selection']
    });
  } catch (_) {}
});

// Handle context menu click
chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId === 'quizlens-solve-selection' && tab?.id) {
    chrome.tabs.sendMessage(tab.id, { type: 'TRIGGER_SELECTION_ANALYSIS' }).catch(() => {});
  }
});

/**
 * Retrieves current extension settings
 */
async function getSettings(): Promise<ExtensionSettings> {
  try {
    const data = await chrome.storage.sync.get('settings');
    const merged = { ...DEFAULT_SETTINGS, ...(data.settings || {}) };
    merged.backendUrl = 'https://quizlens-ai-omega.vercel.app';
    return merged;
  } catch (e) {
    return DEFAULT_SETTINGS;
  }
}

/**
 * Saves extension settings
 */
async function saveSettings(newSettings: Partial<ExtensionSettings>): Promise<ExtensionSettings> {
  const current = await getSettings();
  const updated = { ...current, ...newSettings };
  await chrome.storage.sync.set({ settings: updated });
  return updated;
}

/**
 * Solves question directly from the client without any backend
 */
async function solveDirectly(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const provider = payload.provider || settings.activeProvider;

  if (provider === 'gemini') {
    const key = payload.apiKey || settings.geminiApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithGeminiDirect(payload.question, payload.options, key, payload.model || settings.geminiModel, payload.questionType);
  }

  if (provider === 'groq') {
    const key = payload.apiKey || settings.groqApiKey;
    if (!key) throw new Error('NO_API_KEY');
    const rawModel = payload.model || settings.groqModel || 'llama-3.3-70b-versatile';
    const groqModel = rawModel.includes('mixtral') ? 'llama-3.3-70b-versatile' : rawModel;
    return solveWithGroqDirect(payload.question, payload.options, key, groqModel, payload.questionType);
  }

  if (provider === 'openai') {
    const key = payload.apiKey || settings.openaiApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithOpenAIDirect(payload.question, payload.options, key, payload.model || settings.openaiModel, payload.questionType);
  }

  if (provider === 'deepseek') {
    const key = payload.apiKey || settings.deepseekApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithDeepSeekDirect(payload.question, payload.options, key, payload.model || settings.deepseekModel, payload.questionType);
  }

  if (provider === 'openrouter') {
    const key = payload.apiKey || settings.openrouterApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithOpenRouterDirect(payload.question, payload.options, key, payload.model || settings.openrouterModel, payload.questionType);
  }

  throw new Error(`Nhà cung cấp AI không hợp lệ: ${provider}`);
}

/**
 * Makes API call to QuizLens Backend service if running
 */
async function solveWithBackend(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const baseUrl = settings.backendUrl.replace(/\/+$/, '');
  const targetUrl = `${baseUrl}/api/v1/answer`;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 20000);

  const response = await fetch(targetUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      question: payload.question,
      options: payload.options,
      questionType: payload.questionType,
      provider: payload.provider || settings.activeProvider,
      model: payload.model,
      apiKey: payload.apiKey
    }),
    signal: controller.signal
  });

  clearTimeout(timeoutId);

  if (!response.ok) {
    let errorMsg = `Lỗi máy chủ (${response.status})`;
    try {
      const errorJson = await response.json();
      if (errorJson.error?.message) errorMsg = errorJson.error.message;
    } catch (_) {}
    throw new Error(errorMsg);
  }

  const json = (await response.json()) as ApiResponse<AnswerResult>;
  if (!json.success || !json.data) {
    throw new Error(json.error?.message || 'Không có kết quả trả về từ Backend');
  }

  return json.data;
}

/**
 * Primary solving dispatcher: routes through Vercel Backend first,
 * with fallback to Direct AI if Backend is temporarily unavailable and user has a key.
 */
async function handleAnalyzeQuestion(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const activeKey =
    settings.activeProvider === 'gemini'
      ? settings.geminiApiKey
      : settings.activeProvider === 'groq'
      ? settings.groqApiKey
      : settings.activeProvider === 'openai'
      ? settings.openaiApiKey
      : settings.activeProvider === 'deepseek'
      ? settings.deepseekApiKey
      : settings.openrouterApiKey;

  let activeGroqModel = settings.groqModel || 'llama-3.3-70b-versatile';
  if (activeGroqModel.includes('mixtral')) activeGroqModel = 'llama-3.3-70b-versatile';

  const activeModel =
    settings.activeProvider === 'gemini'
      ? settings.geminiModel
      : settings.activeProvider === 'groq'
      ? activeGroqModel
      : settings.activeProvider === 'openai'
      ? settings.openaiModel
      : settings.activeProvider === 'deepseek'
      ? settings.deepseekModel
      : settings.openrouterModel;

  const enrichedPayload: AnalyzeRequestPayload = {
    ...payload,
    provider: payload.provider || settings.activeProvider,
    model: payload.model || activeModel,
    apiKey: payload.apiKey || activeKey || undefined
  };

  // 1. Luôn ưu tiên gửi câu hỏi qua Vercel Backend chung của hệ thống
  try {
    return await solveWithBackend(enrichedPayload, settings);
  } catch (backendErr: any) {
    // 2. Nếu Backend gặp sự cố tạm thời, fallback sang Direct AI nếu người dùng có API Key cá nhân
    if (activeKey && activeKey.trim().length > 0) {
      try {
        return await solveDirectly(enrichedPayload, settings);
      } catch (directErr: any) {
        throw directErr;
      }
    }
    throw backendErr;
  }
}

// Runtime message listener
chrome.runtime.onMessage.addListener((message: RuntimeMessage, _sender, sendResponse) => {
  (async () => {
    try {
      switch (message.type) {
        case 'GET_SETTINGS': {
          const settings = await getSettings();
          sendResponse({ success: true, data: settings });
          break;
        }

        case 'SAVE_SETTINGS': {
          const updated = await saveSettings(message.payload);
          sendResponse({ success: true, data: updated });
          break;
        }

        case 'TEST_CONNECTION': {
          const settings = await getSettings();
          const targetUrl = 'https://quizlens-ai-omega.vercel.app/api/v1/health';

          try {
            // 1. Kiểm tra trạng thái Backend Vercel
            const healthRes = await fetch(targetUrl, { signal: AbortSignal.timeout(4000) });
            const backendOnline = healthRes.ok;

            // 2. Nếu người dùng bấm nút test cụ thể với key
            if (message.payload?.isExplicitTest) {
              const provider = message.payload?.provider || settings.activeProvider;
              const model = message.payload?.model || (
                provider === 'gemini' ? settings.geminiModel :
                provider === 'groq' ? settings.groqModel :
                provider === 'openai' ? settings.openaiModel :
                provider === 'deepseek' ? settings.deepseekModel : settings.openrouterModel
              );
              const apiKey = (message.payload?.apiKey || (
                provider === 'gemini' ? settings.geminiApiKey :
                provider === 'groq' ? settings.groqApiKey :
                provider === 'openai' ? settings.openaiApiKey :
                provider === 'deepseek' ? settings.deepseekApiKey : settings.openrouterApiKey
              ) || '').trim();

              if (!apiKey || apiKey.length < 5) {
                sendResponse({
                  success: false,
                  error: 'Vui lòng nhập API Key trước khi kiểm tra!'
                });
                break;
              }

              try {
                if (provider === 'gemini') {
                  await solveWithGeminiDirect('1+1=?', { A: '1', B: '2' }, apiKey, model);
                } else if (provider === 'groq') {
                  await solveWithGroqDirect('1+1=?', { A: '1', B: '2' }, apiKey, model);
                } else if (provider === 'openai') {
                  await solveWithOpenAIDirect('1+1=?', { A: '1', B: '2' }, apiKey, model);
                } else if (provider === 'deepseek') {
                  await solveWithDeepSeekDirect('1+1=?', { A: '1', B: '2' }, apiKey, model);
                } else {
                  await solveWithOpenRouterDirect('1+1=?', { A: '1', B: '2' }, apiKey, model);
                }

                sendResponse({
                  success: true,
                  data: {
                    connected: true,
                    message: `Kết nối thành công tới ${provider.toUpperCase()} (${model})!`
                  }
                });
              } catch (aiErr: any) {
                sendResponse({
                  success: false,
                  error: aiErr.message || `Lỗi xác thực ${provider.toUpperCase()}`
                });
              }
              break;
            }

            // Mặc định (khi mở popup): Báo trạng thái Backend
            if (backendOnline) {
              sendResponse({
                success: true,
                data: { connected: true, message: 'Backend Vercel Online' }
              });
            } else {
              sendResponse({
                success: false,
                error: 'Backend Vercel đang bận hoặc ngoại tuyến.'
              });
            }
          } catch (e: any) {
            sendResponse({
              success: false,
              error: 'Không thể kết nối tới Backend Vercel (https://quizlens-ai-omega.vercel.app)'
            });
          }
          break;
        }

        case 'TEST_AI_KEY': {
          const { provider, model, apiKey } = message.payload;
          try {
            const answerRes = await fetch('https://quizlens-ai-omega.vercel.app/api/v1/answer', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                question: 'Thủ đô của Việt Nam là gì?',
                options: { A: 'Hà Nội', B: 'TP.HCM' },
                provider,
                model,
                apiKey
              }),
              signal: AbortSignal.timeout(10000)
            });
            const answerJson = await answerRes.json();
            if (answerRes.ok && answerJson.success) {
              sendResponse({ success: true, data: answerJson.data });
            } else {
              sendResponse({ success: false, error: answerJson.error?.message || 'Lỗi từ AI Provider' });
            }
          } catch (e: any) {
            try {
              let res: AnswerResult;
              if (provider === 'gemini') res = await solveWithGeminiDirect('Thủ đô?', { A: 'HN', B: 'SG' }, apiKey, model);
              else if (provider === 'groq') res = await solveWithGroqDirect('Thủ đô?', { A: 'HN', B: 'SG' }, apiKey, model);
              else if (provider === 'openai') res = await solveWithOpenAIDirect('Thủ đô?', { A: 'HN', B: 'SG' }, apiKey, model);
              else if (provider === 'deepseek') res = await solveWithDeepSeekDirect('Thủ đô?', { A: 'HN', B: 'SG' }, apiKey, model);
              else res = await solveWithOpenRouterDirect('Thủ đô?', { A: 'HN', B: 'SG' }, apiKey, model);
              sendResponse({ success: true, data: res });
            } catch (err: any) {
              sendResponse({ success: false, error: err.message });
            }
          }
          break;
        }

        case 'ANALYZE_QUESTION': {
          const settings = await getSettings();
          const result = await handleAnalyzeQuestion(message.payload, settings);
          sendResponse({ success: true, data: result });
          break;
        }

        default:
          sendResponse({ success: false, error: 'Hành động không hợp lệ' });
      }
    } catch (error: any) {
      sendResponse({ success: false, error: error.message || 'Lỗi không xác định' });
    }
  })();

  return true;
});
